func formatPicture(picture string, val decimal.Decimal) string {
	// handle sign: values are non-negative in this program, but keep generic
	neg := val.IsNegative()
	if neg {
		val = val.Neg()
	}
	// count integer placeholders and fractional placeholders
	dotIdx := strings.Index(picture, ".")
	var intPic string
	var fracPic string
	if dotIdx >= 0 {
		intPic = picture[:dotIdx]
		fracPic = picture[dotIdx+1:]
	} else {
		intPic = picture
		fracPic = ""
	}
	nIntPlace := 0
	for _, c := range intPic {
		if c == 'Z' || c == '9' {
			nIntPlace++
		}
	}
	nFracPlace := 0
	for _, c := range fracPic {
		if c == 'Z' || c == '9' {
			nFracPlace++
		}
	}

	// quantize to nFracPlace fractional digits (already should be)
	// get integer and fractional parts
	// Use string representation to avoid float
	// val is already at correct scale, but ensure trunc
	q := val.Truncate(int32(nFracPlace))

	var intPart int64
	var fracPart int64
	if nFracPlace > 0 {
		scale := decimal.New(1, int32(nFracPlace)) // 10^n
		// integer part
		intDec := q.Truncate(0)
		intPartDec := intDec
		fracDec := q.Sub(intDec).Abs().Mul(scale)
		// due to decimal representation, fracDec should be integer
		intPart = intPartDec.IntPart()
		if intPart < 0 {
			intPart = -intPart
		}
		fracPart = fracDec.IntPart()
		if fracPart < 0 {
			fracPart = -fracPart
		}
	} else {
		intPart = q.IntPart()
		if intPart < 0 {
			intPart = -intPart
		}
	}

	// integer string padded / truncated to nIntPlace low-order digits
	var intStr string
	if nIntPlace > 0 {
		mod := int64(1)
		for i := 0; i < nIntPlace; i++ {
			mod *= 10
		}
		if nIntPlace < 19 {
			intPart = intPart % mod
		}
		intStr = fmt.Sprintf("%0*d", nIntPlace, intPart)
		if len(intStr) > nIntPlace {
			intStr = intStr[len(intStr)-nIntPlace:]
		}
		// also handle case where val had more integer digits via decimal > int64
		// fallback using decimal string for large values
		// Use decimal's integer part string for correctness if overflow
		if intPart == 0 {
			// check if decimal integer part had overflowed int64, use decimal string
			s := q.Abs().StringFixed(0) // integer part string
			// s may be large, take low-order
			if len(s) > nIntPlace {
				s = s[len(s)-nIntPlace:]
			} else if len(s) < nIntPlace {
				s = strings.Repeat("0", nIntPlace-len(s)) + s
			}
			intStr = s
		}
	}

	fracStr := ""
	if nFracPlace > 0 {
		fracStr = fmt.Sprintf("%0*d", nFracPlace, fracPart)
		if len(fracStr) > nFracPlace {
			fracStr = fracStr[len(fracStr)-nFracPlace:]
		}
		// fallback for large: use decimal formatting
		absStr := q.Abs().StringFixed(int32(nFracPlace))
		if dot := strings.Index(absStr, "."); dot >= 0 {
			f := absStr[dot+1:]
			if len(f) > nFracPlace {
				f = f[len(f)-nFracPlace:]
			} else if len(f) < nFracPlace {
				f = f + strings.Repeat("0", nFracPlace-len(f))
			}
			fracStr = f
			ip := absStr[:dot]
			if len(ip) > nIntPlace {
				ip = ip[len(ip)-nIntPlace:]
			} else if len(ip) < nIntPlace {
				ip = strings.Repeat("0", nIntPlace-len(ip)) + ip
			}
			intStr = ip
		}
	}

	// Build output according to picture
	out := []rune(picture)
	// Fill integer placeholders
	idxInt := 0
	for i, c := range picture {
		if dotIdx >= 0 && i > dotIdx {
			break
		}
		if c == 'Z' || c == '9' {
			if idxInt < len(intStr) {
				out[i] = rune(intStr[idxInt])
			} else {
				out[i] = '0'
			}
			idxInt++
		}
	}
	// Fill fractional placeholders
	idxFrac := 0
	if dotIdx >= 0 {
		for i, c := range picture {
			if i <= dotIdx {
				continue
			}
			if c == 'Z' || c == '9' {
				if idxFrac < len(fracStr) {
					out[i] = rune(fracStr[idxFrac])
				} else {
					out[i] = '0'
				}
				idxFrac++
			}
		}
	}

	// Apply Z suppression for leading zeros
	// Determine suppression: any '0' digit in a Z position that is before first non-zero integer digit is suppressed
	// Commas inside suppressed zone become spaces
	// Find first non-zero integer digit index (over integer placeholders)
	firstNonZero := -1
	for i := 0; i < len(intStr); i++ {
		if intStr[i] != '0' {
			firstNonZero = i
			break
		}
	}
	if firstNonZero == -1 {
		// all zeros - suppression extends up to but not including the last integer placeholder (the 9)
		// So keep suppressed true until last integer placeholder
		// We'll handle below
	}

	// Map integer placeholder index to picture index
	picIntIdx := []int{}
	for i, c := range picture {
		if dotIdx >= 0 && i > dotIdx {
			break
		}
		if c == 'Z' || c == '9' {
			picIntIdx = append(picIntIdx, i)
		}
	}
	suppressed := true
	for k, pi := range picIntIdx {
		dig := intStr[k]
		if dig != '0' {
			suppressed = false
		}
		picChar := picture[pi]
		if suppressed {
			if picChar == 'Z' && dig == '0' {
				out[pi] = ' '
			} else if picChar == '9' && dig == '0' && firstNonZero == -1 && k != len(picIntIdx)-1 {
				// This case is actually handled as not suppressed? In our loop suppressed stays true for all zeros,
				// but the final 9 should print 0. So we need to keep 0 for last position even when suppressed.
				// So if it's the last integer placeholder and all zeros, keep '0'
				// But our code would have turned Z to space, 9 to '0' (we already set '0'), so keep '0'
				// For Z positions we already spaced, for 9 we keep '0'
				// So do nothing: out[pi] already '0'
			} else {
				// Z with non-zero would have been set to digit, keep
			}
			// Note: if all zeros, suppressed remains true through all positions, we want final 9 to be '0'
			// The above keeps it
			if firstNonZero == -1 && k == len(picIntIdx)-1 {
				// last placeholder keep as '0' even though suppressed
				out[pi] = '0'
				// mark suppressed false after? not needed
			}
		} else {
			// not suppressed, out already digit
		}
		// Determine if we should keep suppressed for comma handling
		// suppressed flag should become false once we have passed firstNonZero placeholder
		if firstNonZero != -1 && k >= firstNonZero {
			suppressed = false
		}
		if firstNonZero == -1 && k == len(picIntIdx)-1 {
			suppressed = false
		}
	}
	// Comma suppression: commas that are in suppressed zone become spaces
	// A comma is suppressed if every integer placeholder to its left is suppressed (i.e., still in leading zero zone)
	// We can determine by checking if the next integer placeholder to the right is still before firstNonZero
	// Simpler: iterate picture left to right, keep suppressed state for commas
	supp := true
	// Need to know when we exit suppression: at first non-zero digit position
	for i := 0; i < len(picture); i++ {
		// update supp based on integer placeholders encountered
		// We can update after processing placeholder, but for comma we need state before comma
		c := picture[i]
		if c == ',' {
			if supp {
				out[i] = ' '
			} else {
				out[i] = ','
			}
		} else if c == 'Z' || c == '9' {
			// this is integer placeholder (dot region excluded)
			if dotIdx >= 0 && i > dotIdx {
				supp = false
				continue
			}
			// find which k this is
			// if this digit is non-zero, suppression ends after it
			if out[i] != ' ' && out[i] != ',' {
				// out[i] is digit; if digit != '0' then no longer suppressed for following chars
				if out[i] != '0' {
					supp = false
				} else {
					// if this is the last integer placeholder and all zeros, suppression ends
					// Check if all integer digits are zero
					if firstNonZero == -1 {
						// find if this is last int placeholder
						isLast := true
						for j := i + 1; j < len(picture); j++ {
							pc := picture[j]
							if pc == 'Z' || pc == '9' {
								if dotIdx < 0 || j < dotIdx {
									isLast = false
									break
								}
							}
						}
						if isLast {
							supp = false
						}
					}
				}
			} else {
				// space means still suppressed
			}
		} else if c == '.' {
			supp = false
		}
	}

	if neg {
		// COBOL would show sign, but not needed for this program (no negatives)
		// Prepend minus if possible
		for i := 0; i < len(out); i++ {
			if out[i] == ' ' {
				continue
			}
			if i > 0 && out[i-1] == ' ' {
				out[i-1] = '-'
			} else {
				out[i] = '-'
			}
			break
		}
	}

	return string(out)
}

func formatSalesOrComm(d decimal.Decimal) string {
	return formatPicture("ZZZ,ZZ9.99", d)
}
func formatTotal(d decimal.Decimal) string {
	return formatPicture("ZZZ,ZZZ,ZZ9.99", d)
}
func formatRate(d decimal.Decimal) string {
	return formatPicture("9.99", d)
}
func formatCount(v int64) string {
	return fmt.Sprintf("%03d", v)
}
func formatTier(v int64) string {
	return fmt.Sprintf("%d", v)
}

// helpers for numeric field storage truncation
func storePic9_6V99(d decimal.Decimal) decimal.Decimal {
	// keep only low-order digits that fit (6 int +2 frac) => effectively modulo 1_000_000 for integer part, scale 2
	// Truncate to 2 decimals? Storage will be via compute already rounded/truncated.
	// For this program only WS-COMM and WS-TOTAL use it, values fit.
	return d
}

func mainPara() {
	initPara()
	openSalesFile()
	readPara()
	for !isInputDone() {
		processPara()
	}
	closeSalesFile()
	summaryPara()
}

func initPara() {
	tierTable.TierEntry[0].TierLimit = decimal.NewFromFloat(1000.00)
	tierTable.TierEntry[0].TierRate = decimal.NewFromFloat(2.50)
	tierTable.TierEntry[1].TierLimit = decimal.NewFromFloat(5000.00)
	tierTable.TierEntry[1].TierRate = decimal.NewFromFloat(4.00)
	tierTable.TierEntry[2].TierLimit = decimal.NewFromFloat(20000.00)
	tierTable.TierEntry[2].TierRate = decimal.NewFromFloat(5.50)
	tierTable.TierEntry[3].TierLimit = decimal.NewFromFloat(999999.99)
	tierTable.TierEntry[3].TierRate = decimal.NewFromFloat(7.25)
	// Ensure exact decimals
	tierTable.TierEntry[0].TierLimit = decimal.New(100000, -2)
	tierTable.TierEntry[0].TierRate = decimal.New(250, -2)
	tierTable.TierEntry[1].TierLimit = decimal.New(500000, -2)
	tierTable.TierEntry[1].TierRate = decimal.New(400, -2)
	tierTable.TierEntry[2].TierLimit = decimal.New(2000000, -2)
	tierTable.TierEntry[2].TierRate = decimal.New(550, -2)
	tierTable.TierEntry[3].TierLimit = decimal.New(99999999, -2)
	tierTable.TierEntry[3].TierRate = decimal.New(725, -2)
}

func openSalesFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		// if file not exists, treat as empty
		salesFileHandle = nil
		salesFile = bufio.NewScanner(strings.NewReader(""))
		return
	}
	salesFileHandle = f
	salesFile = bufio.NewScanner(f)
	// keep default split (ScanLines)
}

func closeSalesFile() {
	if salesFileHandle != nil {
		salesFileHandle.Close()
	}
}

func readPara() {
	if salesFile == nil || !salesFile.Scan() {
		WsEofFlag = "Y"
		return
	}
	line := salesFile.Text()
	// pad with spaces to 12
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	srId := line[0:4]
	srSalesRaw := line[4:12]
	// PIC 9(6)V99 digits only
	trimmed := strings.TrimSpace(srSalesRaw)
	if trimmed == "" {
		trimmed = "0"
	}
	// keep only digits
	digits := ""
	for _, ch := range trimmed {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		digits = "0"
	}
	// Parse as integer then shift -2
	// Ensure 8 digits interpreted? If fewer digits, treat as integer with implied decimal
	// e.g., "000100000" => 100000 => 1000.00
	decInt, _ := decimal.NewFromString(digits)
	srSales := decInt.Shift(-2)
	salesRec.SrId = srId
	salesRec.SrSales = srSales
}

func processPara() {
	WsTier = 0
	for WsIdx = 1; WsIdx <= 4 && !(WsTier > 0); WsIdx++ {
		limit := tierTable.TierEntry[WsIdx-1].TierLimit
		if salesRec.SrSales.Cmp(limit) <= 0 {
			WsTier = WsIdx
		}
	}
	// COMPUTE WS-COMM ROUNDED = SR-SALES * TIER-RATE /100
	rate := tierTable.TierEntry[WsTier-1].TierRate
	prod := salesRec.SrSales.Mul(rate)
	div := prod.Shift(-2) // /100
	WsComm = div.Round(2)
	// ADD
	WsTotal = WsTotal.Add(WsComm)
	WsCount++
	WsSalesEd = formatSalesOrComm(salesRec.SrSales)
	WsRateEd = formatRate(rate)
	WsCommEd = formatSalesOrComm(WsComm)
	// DISPLAY SR-ID " T" WS-TIER " " WS-SALES-ED " " WS-RATE-ED "% " WS-COMM-ED
	fmt.Printf("%s T%s %s %s%% %s\n", salesRec.SrId, formatTier(WsTier), WsSalesEd, WsRateEd, WsCommEd)
	readPara()
}

func summaryPara() {
	WsTotalEd = formatTotal(WsTotal)
	fmt.Printf("REPS: %s TOTAL: %s\n", formatCount(WsCount), WsTotalEd)
}

