	tierTable.TierEntry[2].TierLimit = decimal.New(2000000, -2)
	tierTable.TierEntry[2].TierRate = decimal.New(550, -2)
	tierTable.TierEntry[3].TierLimit = decimal.New(99999999, -2)
	tierTable.TierEntry[3].TierRate = decimal.New(725, -2)
}

func openSalesFile() {
	f, err := os.Open("input.dat")
	if err != nil {
		salesFileHandle = nil
		salesFile = bufio.NewScanner(strings.NewReader(""))
		return
	}
	salesFileHandle = f
	salesFile = bufio.NewScanner(f)
}

func closeSalesFile() {
	if salesFileHandle != nil {
		salesFileHandle.Close()
	}
}

func readPara() {
	if salesFile == nil || !salesFile.Scan() {
		WsEofFlag = "Y"
		return
	}
	line := salesFile.Text()
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	srId := line[0:4]
	srSalesRaw := line[4:12]
	trimmed := strings.TrimSpace(srSalesRaw)
	if trimmed == "" {
		trimmed = "0"
	}
	digits := ""
	for _, ch := range trimmed {
		if ch >= '0' && ch <= '9' {
			digits += string(ch)
		}
	}
	if digits == "" {
		digits = "0"
	}
	decInt, _ := decimal.NewFromString(digits)
	srSales := decInt.Shift(-2)
	salesRec.SrId = srId
	salesRec.SrSales = srSales
}

func processPara() {
	WsTier = 0
	for WsIdx = 1; WsIdx <= 4 && !(WsTier > 0); WsIdx++ {
		limit := tierTable.TierEntry[WsIdx-1].TierLimit
		if salesRec.SrSales.Cmp(limit) <= 0 {
			WsTier = WsIdx
		}
	}
	rate := tierTable.TierEntry[WsTier-1].TierRate
	prod := salesRec.SrSales.Mul(rate)
	div := prod.Shift(-2)
	WsComm = div.Round(2)
	WsTotal = WsTotal.Add(WsComm)
	WsCount++
	WsSalesEd = formatSalesOrComm(salesRec.SrSales)
	WsRateEd = formatRate(rate)
	WsCommEd = formatSalesOrComm(WsComm)
	fmt.Printf("%s T%s %s %s%% %s\n", salesRec.SrId, formatTier(WsTier), WsSalesEd, WsRateEd, WsCommEd)
	readPara()
}

func summaryPara() {
	WsTotalEd = formatTotal(WsTotal)
	fmt.Printf("REPS: %s TOTAL: %s\n", formatCount(WsCount), WsTotalEd)
}
